// Guards the derived augment flags in data/sets/set17/augment-effects.json
// (generated by scripts/derive-augment-effects.js).
//
// The whole justification for shipping derived data is that it was MEASURED
// against the hand-curated buckets rather than trusted. That measurement has to
// live somewhere that fails, or the next regeneration can quietly halve its
// accuracy and nothing notices — the rules would just start judging augments on
// a wrong premise, silently, which is exactly the failure mode this project
// keeps designing against.
//
// Thresholds are set below the numbers observed when the file was generated
// (economy 46/46, items 143/146), leaving headroom for Riot rewording a
// description without letting a real regression through.

import { describe, it, expect } from 'vitest';
import { readFileSync } from 'fs';
import path from 'path';
import type { AugmentEffect } from '../src/shared/types';

const DATA = path.resolve(__dirname, '..', 'data', 'sets', 'set17');

function readJson<T>(file: string): T {
  return JSON.parse(readFileSync(path.join(DATA, file), 'utf-8')) as T;
}

const effects = readJson<Record<string, AugmentEffect | string | object>>('augment-effects.json');
const buckets = readJson<Record<string, string[]>>('augments.json');

function effectFor(id: string): AugmentEffect | undefined {
  if (id.startsWith('_')) return undefined;
  const e = effects[id];
  return e && typeof e === 'object' && !Array.isArray(e) ? (e as AugmentEffect) : undefined;
}

/** Share of `ids` whose derived entry carries `flag`. */
function coverage(ids: string[], flag: 'economy' | 'items'): { hit: number; total: number } {
  const hit = ids.filter(id => effectFor(id)?.[flag]).length;
  return { hit, total: ids.length };
}

describe('derived augment effects', () => {
  it('was generated and records its provenance', () => {
    expect(Object.keys(effects).length).toBeGreaterThan(100);
    const generated = effects._generated as { dataDragonVersion?: string; augmentsScanned?: number };
    expect(generated?.dataDragonVersion).toBeTruthy();
    expect(generated?.augmentsScanned).toBeGreaterThan(500);
  });

  it('every flag carries the evidence phrase that justified it', () => {
    // An entry with a bare `true` would be an assertion with nothing behind it.
    const unjustified: string[] = [];
    for (const id of Object.keys(effects)) {
      const e = effectFor(id);
      if (!e) continue;
      if ('economy' in e && typeof e.economy !== 'string') unjustified.push(`${id}.economy`);
      if ('items' in e && typeof e.items !== 'string') unjustified.push(`${id}.items`);
    }
    expect(unjustified).toEqual([]);
  });

  it('recovers the hand-curated economy bucket almost exactly', () => {
    const { hit, total } = coverage(buckets.economy, 'economy');
    expect(hit / total, `economy recall ${hit}/${total}`).toBeGreaterThanOrEqual(0.95);
  });

  it('recovers the hand-curated items bucket almost exactly', () => {
    const { hit, total } = coverage(buckets.items, 'items');
    expect(hit / total, `items recall ${hit}/${total}`).toBeGreaterThanOrEqual(0.9);
  });

  it('stays quiet on augments the curator judged to be pure combat', () => {
    // Some overlap is correct and expected — "Gain a random Tank item" really
    // does grant an item, and "gain 2 XP at the start of combat" really is
    // economy. What must not happen is the flags firing across most of the
    // combat bucket, which would mean they are matching stat text rather than
    // grants.
    const econ = coverage(buckets.combat, 'economy');
    const items = coverage(buckets.combat, 'items');
    expect(econ.hit / econ.total, `economy in combat ${econ.hit}/${econ.total}`).toBeLessThan(0.15);
    expect(items.hit / items.total, `items in combat ${items.hit}/${items.total}`).toBeLessThan(0.15);
  });

  it('marks Realm of the Gods blessings as god augments, not economy or items', () => {
    const gods = Object.keys(effects).filter(id => effectFor(id)?.godAugment);
    expect(gods.length).toBeGreaterThan(0);
    for (const id of gods) {
      expect(id, `${id} should look like a god blessing`).toMatch(/_Augment_[A-Za-z]+GodAugment/);
      // A blessing must never also carry a regular flag — checkers/augments.ts
      // short-circuits on godAugment, and a dual-flagged entry would mean the
      // generator disagreed with itself.
      expect(effectFor(id)!.economy).toBeUndefined();
      expect(effectFor(id)!.items).toBeUndefined();
    }
  });

  it('covers the god blessings that actually appear in the golden matches', () => {
    for (const god of ['Soraka', 'Thresh', 'Kayle']) {
      const match = Object.keys(effects).find(id => id.includes(`${god}GodAugment`));
      expect(match, `${god}'s blessing should be marked`).toBeTruthy();
      expect(effectFor(match!)!.godAugment).toBe(true);
    }
  });
});
